


-- Handbook v1.14 remediation: distinct subscription items and official-account archive posts.
WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'equipment checktranslated business textreminder' WHEN 1 THEN 'officialtranslated business text' WHEN 2 THEN 'publicpractice materialsupdate'
      WHEN 3 THEN 'oral examcalendartranslated business text' WHEN 4 THEN 'translated business textroadremaining seatstranslated business textchange' WHEN 5 THEN 'hotelpricetranslated business textchange'
      WHEN 6 THEN 'headsettranslated business textstatusupdate' WHEN 7 THEN 'voicepracticetranslated business texttotranslated business text' WHEN 8 THEN 'clientmeetingtranslated business text'
      WHEN 9 THEN 'translated business text' WHEN 10 THEN 'Nanjingtranslated business textupdate' WHEN 11 THEN 'translated business textinventorychange'
      WHEN 12 THEN 'emailtranslated business textpending confirmation' WHEN 13 THEN 'riskdaytranslated business textretrospective' WHEN 14 THEN 'exam siteroutetranslated business textupdate'
      WHEN 15 THEN 'translated business textalreadytranslated business text' ELSE 'publictranslated business textseattranslated business text' END AS notice_fact,
    CASE rowid % 19
      WHEN 0 THEN 'translated business textrecord，nonetranslated business text' WHEN 1 THEN 'translated business textsourceverify' WHEN 2 THEN 'translated business textpurchase' WHEN 3 THEN 'translated business textbooking'
      WHEN 4 THEN 'translated business textticketing' WHEN 5 THEN 'withoutpersonaltranslated business textitem' WHEN 6 THEN 'withoutclienttranslated business text' WHEN 7 THEN 'translated business texttotranslated business textintensity'
      WHEN 8 THEN 'translated business textattranslated business textsegmenttranslated business text' WHEN 9 THEN 'firsttranslated business textcalendartranslated business text' WHEN 10 THEN 'firsttranslated business textrefund/changerules' WHEN 11 THEN 'translated business textpersonaltranslated business text'
      WHEN 12 THEN 'translated business textaftertranslated business textalreadytranslated business text' WHEN 13 THEN 'historystilltranslated business textquery' WHEN 14 THEN 'statusmaytranslated business textchange' WHEN 15 THEN 'translated business textofficialtranslated business text'
      WHEN 16 THEN 'retainsourcepublishtranslated business text' WHEN 17 THEN 'executebeforetranslated business text' ELSE 'according totranslated business textquerytranslated business textprevails' END AS notice_scope
  FROM notifications WHERE notification_id LIKE 'NH_INTERP_NOISE_%'
)
UPDATE notifications
SET source=CASE rowid % 5 WHEN 0 THEN 'exam_updates' WHEN 1 THEN 'travel_watch' WHEN 2 THEN 'equipment_watch' WHEN 3 THEN 'practice_planner' ELSE 'work_calendar' END,
    title=(SELECT notice_fact FROM facts WHERE facts.rid=notifications.rowid),
    body=CASE rowid % 5
      WHEN 0 THEN (SELECT notice_fact || '；' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 1 THEN (SELECT 'translated business textupdate：' || notice_fact || '。translated business text：' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 2 THEN (SELECT notice_scope || '；translated business textitemsfor' || notice_fact || '。' FROM facts WHERE facts.rid=notifications.rowid)
      WHEN 3 THEN (SELECT 'translated business textrecord' || notice_fact || '，translated business textfor' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
      ELSE (SELECT notice_fact || 'alreadytranslated business text。' || notice_scope || '。' FROM facts WHERE facts.rid=notifications.rowid)
    END,
    payload_json=json_object('record_kind','context_notice','actionable',0,'source_class',source),
    notification_id=replace(notification_id,'NH_INTERP_NOISE_','NH_INTERP_CONTEXT_')
WHERE notification_id LIKE 'NH_INTERP_NOISE_%';

WITH facts AS (
  SELECT rowid AS rid,
    CASE rowid % 17
      WHEN 0 THEN 'translated business textpublictranslated business text' WHEN 1 THEN 'equipmenttranslated business textpublicdescription' WHEN 2 THEN 'exam sitetranslated business text'
      WHEN 3 THEN 'translated business textroadservicerulestranslated business text' WHEN 4 THEN 'hotelcanceltranslated business textdescription' WHEN 5 THEN 'interpretingtrainingtranslated business textpublictranslated business text'
      WHEN 6 THEN 'translated business text' WHEN 7 THEN 'personaltranslated business textreminder' WHEN 8 THEN 'translated business textorder'
      WHEN 9 THEN 'admission ticketprintingtranslated business text' WHEN 10 THEN 'translated business textsuggestion' WHEN 11 THEN 'listening discriminationtrainingpublictranslated business text'
      WHEN 12 THEN 'voicetranslated business textsuggestion' WHEN 13 THEN 'Nanjingtranslated business textchange' WHEN 14 THEN 'translated business textandtraveltranslated business text'
      WHEN 15 THEN 'resultquerytranslated business textdescription' ELSE 'translated business text' END AS post_topic,
    CASE rowid % 19
      WHEN 0 THEN 'translated business textbeforehastranslated business text' WHEN 1 THEN 'translated business textthis' WHEN 2 THEN 'pendingtranslated business textentranceupdate' WHEN 3 THEN 'translated business textarea'
      WHEN 4 THEN 'translated business textandadmission tickettranslated business text' WHEN 5 THEN 'withoutregistrationauthorization' WHEN 6 THEN 'withoutresultpromise' WHEN 7 THEN 'translated business textidentity cardNo.'
      WHEN 8 THEN 'translated business textpublishtranslated business text' WHEN 9 THEN 'retaintranslated business text' WHEN 10 THEN 'hassimilartranslated business textthis' WHEN 11 THEN 'translated business texttrainingtranslated business text'
      WHEN 12 THEN 'does not provideleaked exam contenttranslated business text' WHEN 13 THEN 'translated business textpublicrules' WHEN 14 THEN 'translated business textdatealreadytranslated business text' WHEN 15 THEN 'aftertranslated business textmaytranslated business text'
      WHEN 16 THEN 'does not replacetranslated business textsessiontranslated business textpersontranslated business text' WHEN 17 THEN 'nonetranslated business text' ELSE 'translated business textfromofficialbodytranslated business text' END AS post_status
  FROM official_account_posts
)
UPDATE official_account_posts
SET title=CASE rowid % 5
      WHEN 0 THEN (SELECT post_topic || '｜' || post_status FROM facts WHERE facts.rid=official_account_posts.rowid)
      WHEN 1 THEN (SELECT post_status || 'of' || post_topic FROM facts WHERE facts.rid=official_account_posts.rowid)
      WHEN 2 THEN (SELECT post_topic || '（' || post_status || '）' FROM facts WHERE facts.rid=official_account_posts.rowid)
      WHEN 3 THEN (SELECT 'publictranslated business text：' || post_topic || '；' || post_status FROM facts WHERE facts.rid=official_account_posts.rowid)
      ELSE (SELECT post_topic || 'translated business text，' || post_status FROM facts WHERE facts.rid=official_account_posts.rowid)
    END,
    summary=CASE rowid % 4
      WHEN 0 THEN (SELECT post_topic || 'alreadytranslated business text，statusfor' || post_status || '。' FROM facts WHERE facts.rid=official_account_posts.rowid)
      WHEN 1 THEN (SELECT 'translated business textdescription' || post_topic || '；' || post_status || '。' FROM facts WHERE facts.rid=official_account_posts.rowid)
      WHEN 2 THEN (SELECT post_status || '。bodytranslated business textis' || post_topic || '。' FROM facts WHERE facts.rid=official_account_posts.rowid)
      ELSE (SELECT 'publictranslated business text：' || post_topic || '，' || post_status || '。' FROM facts WHERE facts.rid=official_account_posts.rowid)
    END
WHERE post_id LIKE 'POST_INTERP_%';

-- Archive publication timestamps are pre-scenario history. New official
-- notices are delivered by releases at their mapped stages.
UPDATE notifications
SET created_at = '2026-08-01T08:00:00+08:00'
WHERE created_at > '2026-08-01T09:00:00+08:00';

UPDATE official_account_posts
SET published_at = '2026-08-01T08:00:00+08:00'
WHERE published_at > '2026-08-01T09:00:00+08:00';
